CREATE TABLE portfolios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, country VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, asset_type VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE holdings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, portfolio_id BIGINT NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE, symbol VARCHAR(20) NOT NULL, instrument_name VARCHAR(160) NOT NULL, quantity DECIMAL(24,8) NOT NULL, average_cost DECIMAL(20,6) NOT NULL, market_value DECIMAL(20,6), currency VARCHAR(3) NOT NULL, UNIQUE(portfolio_id,symbol));
CREATE TABLE watchlists (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(40) NOT NULL, market VARCHAR(10) NOT NULL, currency VARCHAR(3) NOT NULL);
CREATE TABLE watchlist_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, watchlist_id BIGINT NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, symbol VARCHAR(15) NOT NULL, name VARCHAR(160) NOT NULL, price DECIMAL(20,6), change_percent DECIMAL(12,6), trend VARCHAR(12), asset_type VARCHAR(50), sector VARCHAR(100), score DECIMAL(8,3), volume VARCHAR(60), metrics CLOB, UNIQUE(watchlist_id,symbol));
CREATE TABLE user_preferences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_key VARCHAR(120) NOT NULL UNIQUE, favorite_watchlists CLOB NOT NULL, favorite_symbols CLOB NOT NULL, watchlist_columns CLOB NOT NULL);
